const AR2='<defs><marker id="ar2" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L8 4L0 8z" style="fill:var(--mut)"/></marker></defs>';
const BX=(x,y,w,h,c,t1,t2,t3,fs)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" style="fill:var(--s1);stroke:${c}"/>`+T(x+w/2,y+11,t1,`text-anchor="middle" style="font-size:${fs||7.2}px;font-weight:800;fill:${c}"`)+(t2?T(x+w/2,y+21,t2,'text-anchor="middle" style="font-size:6.2px"'):'')+(t3?T(x+w/2,y+30,t3,'text-anchor="middle" style="font-size:6.2px;fill:var(--mut)"'):'');
const SGN=(x,y,s)=>`<circle cx="${x}" cy="${y}" r="7" style="fill:${s==='+'?'var(--up)':s==='−'?'var(--dn)':'var(--mut)'};fill-opacity:.85"/>`+T(x,y+3,s,'text-anchor="middle" style="font-size:9px;font-weight:800;fill:var(--bg)"');
const LESSONS2=[
 /* ---------- cấp 3: hiểu mình ---------- */
 {id:'l3-profile',t:'Know yourself before picking stocks',d:'Goals, time horizon, risk appetite',
  vis:()=>{ let g=''; const rows=[['Time horizon','under 2 yrs','over 10 yrs',.75],['Drop you can bear','−10%','−40%',.55],['Income stability','shaky','solid',.7]];
    rows.forEach(([n,a,b,v],i)=>{ const y=12+i*30; g+=T(6,y,n,'style="font-size:7.2px;font-weight:700"')+`<line x1="6" x2="116" y1="${y+9}" y2="${y+9}" style="stroke:var(--line2)" stroke-width="3" stroke-linecap="round"/><circle cx="${6+v*110}" cy="${y+9}" r="4.5" style="fill:var(--gold)"/>`+T(6,y+20,a,'style="font-size:5.8px;fill:var(--mut)"')+T(116,y+20,b,'text-anchor="end" style="font-size:5.8px;fill:var(--mut)"'); });
    const pr=[['Conservative',30,'var(--us)'],['Balanced',60,'var(--gold)'],['Growth',85,'var(--up)']];
    pr.forEach(([n,p,c],i)=>{ const y=8+i*30; g+=`<rect x="128" y="${y}" width="68" height="26" rx="5" style="fill:var(--s1);stroke:${c}"/><rect x="132" y="${y+17}" width="${p*0.6}" height="4" rx="2" style="fill:${c}"/>`+T(162,y+9,n,'text-anchor="middle" style="font-size:6.6px;font-weight:800"')+T(162,y+15.5,p+'% stocks','text-anchor="middle" style="font-size:5.6px"'); });
    g+=T(100,118,'Your answers set your stock allocation','text-anchor="middle" '+TB);
    return sv(g,'Three questions that define your investor profile and stock allocation'); },
  f:'The right stock allocation depends on: how long until you need the money + the drop you can bear + how stable your income is',
  pts:['Before asking “which stock should I buy”, answer this: what is this money for, when will you need it, and would losing 30% affect your daily life?','A reality check: if your portfolio fell 30% in three months, would you panic-sell, sit tight or buy more? Your honest answer sets your stock allocation.','Someone young, with a stable income and no need for the money for 10 years, can hold more stocks than someone close to retirement.','Knowledge is part of risk appetite too: if you cannot yet read financial statements, lean on index funds more than individual stocks.','Write a one-page “personal investment policy”: goals, allocation, buy and sell rules. Reread it whenever the market makes you panic.'],
  thr:[['Conservative','About 20–40% stocks, the rest in deposits and bonds'],['Balanced','About 50–70% stocks'],['Growth','About 80–100% stocks, horizon over 10 years']],
  hook:'<b>Remember:</b> the best portfolio is the one you can hold through a market crash.',src:'CFA Institute, Elements of an Investment Policy Statement for Individual Investors (2010); Vanguard, Investor Questionnaire.'},
 {id:'l3-inflation',t:'Inflation and real returns',d:'Idle money is money losing value',
  vis:()=>{ let g=''; const yrs=[[0,100],[5,82.2],[10,67.6],[15,55.5],[20,45.6]];
    yrs.forEach(([y,v],i)=>{ const x=18+i*38, h=v*0.62; g+=`<rect x="${x}" y="${94-h}" width="26" height="${h}" rx="3" style="fill:var(--gold);fill-opacity:${1-i*.15}"/>`+T(x+13,90-h,fmt(v,1),'text-anchor="middle" style="font-size:7.5px;font-weight:800"')+T(x+13,103,y?'in '+y+' yrs':'today','text-anchor="middle" style="font-size:6.5px"'); });
    g+=T(100,10,'Buying power of 100M VND at 4%/yr inflation','text-anchor="middle" '+TB)+T(100,117,'Savings must beat inflation to truly grow','text-anchor="middle" '+TS);
    return sv(g,'Buying power of 100M VND shrinking with 4% annual inflation'); },
  f:'Real return = (1 + nominal return) ÷ (1 + inflation) − 1 ≈ nominal − inflation',
  pts:['Vietnam’s inflation (CPI) has run at about 3–4% a year in recent years. At 4% a year, money loses half its buying power in about 18 years.','A 5% savings deposit with 3.5% inflation gives a real return of only about 1.4% a year.','A stock is ownership in a business — and businesses raise prices with inflation — so over the long run stocks usually preserve buying power better than cash and fixed-rate bonds.','High inflation pushes interest rates up, and stock valuations often fall in the short run — the short and long run can point in opposite directions.','Always state wealth-building goals in “today’s money”: 5 bn in 20 years is worth only about 2.3 bn today at 4% inflation.'],
  thr:[['Inflation 4%/yr','Buying power halves in ≈ 18 years'],['Negative real return','You are getting poorer even as the balance grows'],['Wealth-building goal','Always convert to today’s money']],
  hook:'<b>Remember:</b> inflation is an invisible tax on people holding cash.',src:'General Statistics Office of Vietnam, Consumer Price Index (CPI); Fisher, The Theory of Interest (1930).'},
 /* ---------- cấp 4: đọc BCTC ---------- */
 {id:'l4-bs',t:'The balance sheet in detail',d:'Current assets, long-term assets and funding',
  vis:()=>{ let g=''; const L=[['Cash & equiv.',18,'var(--up)'],['Receivables',20,'var(--us)'],['Inventory',22,'var(--gold)'],['PP&E, CIP',30,'var(--mut)'],['LT investments',10,'var(--vn)']], R=[['Current liab.',30,'var(--dn)'],['Long-term liab.',20,'var(--dn)'],['Equity',50,'var(--up)']];
    let y=18; L.forEach(([n,h,c])=>{ g+=`<rect x="14" y="${y}" width="74" height="${h*0.9-1}" rx="2" style="fill:${c};fill-opacity:.55"/>`+T(51,y+h*0.45+2,n,'text-anchor="middle" style="font-size:6.6px;font-weight:700"'); y+=h*0.9; });
    y=18; R.forEach(([n,h,c],i)=>{ g+=`<rect x="112" y="${y}" width="74" height="${h*0.9-1}" rx="2" style="fill:${c};fill-opacity:${i===1?.35:.55}"/>`+T(149,y+h*0.45+2,n,'text-anchor="middle" style="font-size:6.6px;font-weight:700"'); y+=h*0.9; });
    g+=T(51,12,'ASSETS','text-anchor="middle" '+TB)+T(149,12,'LIAB. + EQUITY','text-anchor="middle" '+TB)+T(100,64,'=','text-anchor="middle" style="font-size:14px;font-weight:800"');
    g+=T(51,118,'What it owns','text-anchor="middle" '+TS)+T(149,118,'Funded by','text-anchor="middle" '+TS);
    return sv(g,'Balance sheet structure: assets equal liabilities plus equity'); },
  f:'Working capital = Current assets − Current liabilities · Net debt = Short- + long-term borrowings − Cash and cash equivalents',
  pts:['Current assets (under 12 months): cash, short-term financial investments, trade receivables, prepayments to suppliers, other receivables, inventory.','Long-term assets: fixed assets, construction in progress, investment property, investments in associates, goodwill.','Liabilities: trade payables, advances from customers (very large at real estate companies), short- and long-term borrowings, bonds.','Equity: contributed capital, share premium, undistributed net income, non-controlling interests.','Read the trend: compare 4–8 consecutive periods. Any item growing unusually fast relative to revenue is where you should read the notes.','Watch for large “other receivables” and “prepayments to suppliers” — in Vietnam these are sometimes a channel for moving money to related parties.'],
  thr:[['Net debt ÷ Equity below 1','Moderate leverage for a manufacturer'],['Current assets exceed current liabilities','Able to pay debts as they fall due'],['Other receivables, prepayments surging','Read the notes: who is the counterparty?']],
  hook:'<b>Remember:</b> the left side is “what it owns”, the right side is “where the money came from” — the two sides always balance.',src:'Circular 200/2014/TT-BTC (form B01-DN); Vietnamese Accounting Standard VAS 21.'},
 {id:'l4-is',t:'The income statement in detail',d:'Where profit comes from, and whether it repeats',
  vis:()=>{ const st=[['Revenue',100,0,'var(--us)'],['COGS',-70,0,'var(--dn)'],['Gross profit',30,1,'var(--up)'],['SG&A',-14,0,'var(--dn)'],['Fin. cost',-2,0,'var(--dn)'],['Other income',4,0,'var(--gold)'],['Tax',-4,0,'var(--dn)'],['Net income',14,1,'var(--up)']];
    const Y=v=>96-v*0.78; let run=0, g=''; const w=20;
    st.forEach(([n,v,tot,c],i)=>{ const x=8+i*23.5; let a,b; if(tot){ a=0;b=v; run=v; } else { a=run; b=run+v; run=b; }
      g+=`<rect x="${x}" y="${Y(Math.max(a,b))}" width="${w}" height="${Math.max(1,Math.abs(b-a)*0.78)}" rx="2" style="fill:${c};fill-opacity:.8"/>`+T(x+w/2,Y(Math.max(a,b))-2,(v>0&&!tot&&i?'+':'')+v,'text-anchor="middle" style="font-size:6.5px;font-weight:700"')+T(x+w/2,106,n.split(' ')[0],'text-anchor="middle" style="font-size:5.8px"')+(n.split(' ').length>1?T(x+w/2,113,n.split(' ').slice(1).join(' '),'text-anchor="middle" style="font-size:5.8px"'):''); });
    g+=T(196,12,'Gold: one-off profit,','text-anchor="end" style="font-size:6.3px;fill:var(--gold)"')+T(196,21,'exclude when valuing','text-anchor="end" style="font-size:6.3px;fill:var(--gold)"');
    return sv(g,'Profit waterfall from revenue down to net income'); },
  f:'Operating profit = Gross profit + Financial income − Financial expenses + Share of JV profit − Selling expenses − Admin expenses',
  pts:['Net revenue is after discounts and returns. Cost of goods sold is the direct cost of making the product.','Gross profit ÷ revenue = gross margin, a measure of pricing power. Selling and admin expenses measure operating efficiency.','Financial income and expenses include deposit interest, loan interest, FX differences and gains or losses on securities — all volatile.','“Other income”, gains on asset disposals and revaluation gains on investments are one-offs. When valuing, use core profit with these removed.','EPS is based on net income attributable to parent-company shareholders, not total consolidated net income (which includes non-controlling interests).','Compare this quarter with the same quarter last year (YoY) to remove seasonality; use the sum of the last 4 quarters (TTM) to compute P/E.'],
  thr:[['Other income over 20% of pre-tax profit','Profit is less durable'],['Interest expense over 30% of gross profit','Leverage is eating profit'],['Profit growing much faster than revenue for many quarters','Real margin expansion — or something unusual']],
  hook:'<b>Remember:</b> ask every profit line one question: “will it happen again next year?”',src:'Circular 200/2014/TT-BTC (form B02-DN); VAS 01, VAS 14.'},
 {id:'l4-ratios',t:'Core financial ratios',d:'Liquidity, leverage, efficiency, profitability',
  vis:()=>{ const q=[['LIQUIDITY','var(--us)',['Current = CA ÷ CL','Quick = (CA − Inv.) ÷ CL']],['LEVERAGE','var(--dn)',['Net debt ÷ EBITDA','Coverage = EBIT ÷ Interest']],['EFFICIENCY','var(--gold)',['Asset turn = Rev ÷ Total assets','DSO = AR ÷ Rev × 365']],['PROFITABILITY','var(--up)',['ROE = Net income ÷ Equity','ROIC = EBIT(1−t) ÷ Inv. capital']]];
    let g=''; q.forEach(([n,c,f],i)=>{ const x=6+(i%2)*97, y=8+Math.floor(i/2)*56; g+=`<rect x="${x}" y="${y}" width="91" height="50" rx="7" style="fill:var(--s1);stroke:${c}"/>`+T(x+45.5,y+13,n,`text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:${c}"`)+f.map((t,k)=>T(x+45.5,y+27+k*11,t,'text-anchor="middle" style="font-size:5.4px"')).join(''); });
    return sv(g,'The four groups of core financial ratios'); },
  f:'Read ratios as a 3–5 year trend and against the industry median — a single number says little on its own',
  pts:['Liquidity: current ratio, quick ratio, cash ratio — can the company pay debts as they fall due?','Leverage: debt ÷ equity, net debt ÷ EBITDA (how many years of operating profit to pay off the debt), interest coverage (EBIT ÷ interest expense).','Efficiency: asset turnover, days sales outstanding, days inventory, days payable — how long cash stays “buried”.','Profitability: gross margin, net margin, ROA, ROE, ROIC. A high ROE driven by leverage is lower quality than a high ROE driven by margins (see the DuPont lesson).','Banks, insurers and brokerages use their own ratio sets (see the “Reading statements by industry” lesson).','Each stock’s detail page in the app already computes most of these ratios.'],
  thr:[['Current ratio above 1.2','Liquidity is fine'],['Net debt ÷ EBITDA below 3','Acceptable leverage'],['Interest coverage above 3x','No pressure from interest costs']],
  hook:'<b>Remember:</b> four questions — can it pay its debts, does it borrow too much, does it use assets well, does it earn well?',src:'CFA Institute, Financial Analysis Techniques (CFA Program Curriculum Level I).'},
 {id:'l4-notes',t:'Notes and the audit opinion',d:'Where the most important information hides',
  vis:()=>{ const op=[['Unqualified','Reassuring','var(--up)'],['Emphasis of matter','Read that part','var(--us)'],['Qualified','High caution','var(--gold)'],['Adverse / Disclaimer','Stay away','var(--dn)']];
    let g=T(100,12,'Four levels of audit opinion','text-anchor="middle" '+TB); op.forEach(([a,b,c],i)=>{ const y=20+i*22; g+=`<rect x="8" y="${y}" width="${124-i*12}" height="18" rx="5" style="fill:${c};fill-opacity:.75"/>`+T(14,y+12,a,'style="font-size:7px;font-weight:800;fill:var(--bg)"')+T(194,y+12,b,'text-anchor="end" style="font-size:6.8px;font-weight:700"'); });
    g+=T(100,118,'Read the audit opinion first, the numbers second','text-anchor="middle" '+TS);
    return sv(g,'Levels of audit opinion from safe to risky'); },
  f:'Reading order: Audit opinion → Accounting policies → Related parties → Borrowings, guarantees → Events after the reporting period',
  pts:['An audit opinion has four levels: unqualified; qualified (some figures lack sufficient evidence or are misstated); adverse; disclaimer of opinion. It may include an “emphasis of matter” paragraph, for example doubt about the company’s ability to continue as a going concern.','Stocks with a qualified, adverse or disclaimer opinion can be put on the warning or control list, and even delisted if it happens repeatedly.','The notes detail each item: who the company borrows from, at what interest rate, what collateral, who owes it money, and transactions with companies tied to management.','Compare figures before and after the audit (or the semi-annual review): a large gap in profit signals aggressive accounting.','Consolidated statements cover the whole group; separate statements cover only the parent company. Dividends are paid from the parent company’s undistributed profit.','Frequently changing auditors or filing reports late — a yellow flag for governance.'],
  thr:[['Qualified opinion','Find out why before buying'],['Disclaimer or adverse','Remove from the list'],['Large pre- vs post-audit gap','Trust self-prepared figures less']],
  hook:'<b>Remember:</b> the numbers are on the first page, the truth is in the notes.',src:'Vietnamese Standards on Auditing VSA 700, 705, 706; Circular 96/2020/TT-BTC on information disclosure.'},
 /* ---------- cấp 5: dòng tiền & sức khỏe ---------- */
 {id:'l5-cf3',t:'The three cash flows and the company life cycle',d:'Reading the signs of CFO, CFI, CFF',
  vis:()=>{ let g=''; const hd=['Operating','Investing','Financing']; const st=[['Start-up','−','−','+'],['Growth','+','−','+'],['Mature','+','−','−'],['Decline','−','+','−']];
    hd.forEach((h,i)=>g+=T(96+i*36,14,h,'text-anchor="middle" style="font-size:6.8px;font-weight:800"'));
    st.forEach(([n,a,b,c],r)=>{ const y=30+r*22; g+=`<rect x="6" y="${y-11}" width="188" height="19" rx="5" style="fill:${r===2?'var(--gold-soft, rgba(216,174,87,.15))':'var(--s1)'};stroke:var(--line)"/>`+T(12,y+2,n,'style="font-size:7.4px;font-weight:700"')+SGN(96,y-1.5,a)+SGN(132,y-1.5,b)+SGN(168,y-1.5,c); });
    g+=T(100,120,'Best long-term holdings: mature phase','text-anchor="middle" '+TS);
    return sv(g,'Signs of the three cash flows in each phase of the company life cycle'); },
  f:'Ending cash = Beginning cash + Operating cash flow (CFO) + Investing (CFI) + Financing (CFF)',
  pts:['CFO — operating cash flow: cash collected from customers minus cash paid to suppliers, staff, lenders (interest) and taxes. This is the company’s “lifeblood”.','CFI — investing cash flow: spending on fixed assets (capex), capital contributions, buying and selling subsidiaries, term deposits; usually negative while a company expands.','CFF — financing cash flow: borrowing and repaying debt, issuing shares, paying cash dividends.','Most Vietnamese companies prepare CFO with the indirect method: start from pre-tax profit, add back depreciation, adjust for changes in receivables, inventory and payables.','Look at the combination of signs to tell the life-cycle phase: a mature company has positive CFO and uses it to invest, repay debt and pay dividends (+, −, −).','The most worrying case: profit is positive for years but CFO is negative, so the company keeps borrowing (positive CFF) to fill the gap.'],
  thr:[['CFO ÷ Net income above 1 (3–5 yrs)','Profit turns into real cash'],['CFO negative for years while profitable','Red flag for earnings quality'],['Dividends paid with borrowed money','Not sustainable']],
  hook:'<b>Remember:</b> profit is an opinion, cash is a fact.',src:'VAS 24 (Cash flow statement); Dickinson (2011), Cash Flow Patterns as a Proxy for Firm Life Cycle, The Accounting Review 86(6).'},
 {id:'l5-capex',t:'Capex, depreciation and owner earnings',d:'Money to stand still and money to grow',
  vis:()=>{ let g=''; const parts=[['Maint. capex',30,'var(--dn)'],['Growth capex',35,'var(--us)'],['Free cash',35,'var(--up)']]; let x=10;
    g+=T(100,14,'Operating cash flow = 100','text-anchor="middle" '+TB);
    parts.forEach(([n,v,c])=>{ const w=v*1.8; g+=`<rect x="${x}" y="24" width="${w-2}" height="28" rx="4" style="fill:${c};fill-opacity:.7"/>`+T(x+w/2-1,36,n,'text-anchor="middle" style="font-size:6.6px;font-weight:800;fill:var(--bg)"')+T(x+w/2-1,47,v,'text-anchor="middle" style="font-size:8px;font-weight:800;fill:var(--bg)"'); x+=w; });
    g+=T(10,70,'≈ depreciation: keeps current capacity','style="font-size:6.5px;fill:var(--dn)"')+T(10,82,'Growth: only good if project ROIC > cost of capital','style="font-size:6.5px;fill:var(--us)"')+T(10,94,'Free cash: dividends, buybacks, paying down debt','style="font-size:6.5px;fill:var(--up)"');
    g+=T(100,116,'Owner earnings = NI + D&A − Maint. capex','text-anchor="middle" '+TB);
    return sv(g,'Splitting operating cash flow: maintenance capex, growth capex, free cash'); },
  f:'Owner earnings (Buffett) = Net income + Depreciation − Maintenance capex − Required increase in working capital',
  pts:['Capex is cash spent buying or building fixed assets — see the line “Purchases and construction of fixed assets” in the cash flow statement.','Maintenance capex keeps capacity where it is (replacing old machines); growth capex creates new growth. The statements do not split them; a rough estimate: maintenance capex ≈ depreciation.','FCF = CFO − total capex. A company expanding hard can have temporarily negative FCF — not bad if the projects earn a high ROIC.','“Capital-intensive” businesses (steel, airlines, power) need heavy capex forever just to stand still; “capital-light” businesses (software, online retail, consumer brands) keep more free cash.','Construction in progress that drags on for years without turning into revenue-generating assets is a sign the project is in trouble.'],
  thr:[['Capex ÷ Depreciation near 1','Mostly maintenance, low growth'],['Capex ÷ Depreciation above 2','Expanding hard — check the funding'],['FCF positive for many years','Can pay sustainable dividends']],
  hook:'<b>Remember:</b> depreciation is a real cost — machines will have to be replaced.',src:'Buffett, Berkshire Hathaway Letter to Shareholders 1986 (Owner earnings); Greenwald et al., Value Investing: From Graham to Buffett and Beyond (2001).'},
 {id:'l5-quality',t:'Earnings quality',d:'Does profit turn into cash?',
  vis:()=>{ const X=i=>28+i*36, Y=v=>62-v*0.42; let g=`<line class="grid-l" x1="20" x2="190" y1="${Y(0)}" y2="${Y(0)}"/>`;
    const A=[[60,64],[70,75],[80,86],[90,94],[100,108]], B=[[60,40],[80,20],[100,-10],[125,-30],[150,-45]];
    const pl=(arr,k,c,dash)=>`<path d="${arr.map((p,i)=>(i?'L':'M')+X(i)+' '+Y(p[k])).join(' ')}" fill="none" style="stroke:${c}" stroke-width="1.8"${dash?' stroke-dasharray="3 2"':''}/>`;
    g+=`<g transform="translate(0,0) scale(.5,1)">${''}</g>`;
    const half=(arr,dx,c)=>arr.map((p,i)=>`<circle cx="${(X(i)*0.45+dx).toFixed(1)}" cy="${Y(p[0])}" r="2" style="fill:var(--gold)"/><circle cx="${(X(i)*0.45+dx).toFixed(1)}" cy="${Y(p[1])}" r="2" style="fill:${c}"/>`).join('')+`<path d="${arr.map((p,i)=>(i?'L':'M')+(X(i)*0.45+dx).toFixed(1)+' '+Y(p[0])).join(' ')}" fill="none" style="stroke:var(--gold)" stroke-width="1.6"/><path d="${arr.map((p,i)=>(i?'L':'M')+(X(i)*0.45+dx).toFixed(1)+' '+Y(p[1])).join(' ')}" fill="none" style="stroke:${c}" stroke-width="1.6" stroke-dasharray="3 2"/>`;
    g+=half(A,0,'var(--up)')+half(B,98,'var(--dn)');
    g+=T(45,96,'Company A','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--up)"')+T(45,106,'cash tracks profit','text-anchor="middle" style="font-size:6.3px"')+T(143,96,'Company B','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--dn)"')+T(143,106,'profit up, cash negative','text-anchor="middle" style="font-size:6.3px"');
    g+=T(100,118,'Gold: profit · Dashed: operating CF · 5-year illustration','text-anchor="middle" style="font-size:6.4px"');
    return sv(g,'Profit versus cash flow for two illustrative companies'); },
  f:'Accrual ratio = (Net income − CFO) ÷ Average total assets · Goal: CFO ÷ Net income ≥ 1',
  pts:['Accrual accounting records revenue when a sale is made, not when cash is collected — so profit and cash can diverge, especially with credit sales.','Sloan’s study (1996): companies with a large “accrual” component of profit (not backed by cash) tend to have weaker earnings and stock prices later.','Signs of low-quality earnings: receivables growing faster than revenue, swelling inventory, capitalizing interest into assets, reversing provisions, revaluation gains.','Check days sales outstanding (DSO): a sudden jump means the company is loosening credit terms to “push” revenue.','High-quality earnings: CFO close to or above net income for many years, stable margins, few unusual items.'],
  thr:[['Accrual ratio above 10% of assets','Warning'],['DSO up more than 30% in a year','Look into credit policy'],['3-year average CFO ÷ Net income below 0.5','Profit is hard to believe']],
  hook:'<b>Remember:</b> revenue not yet collected is only a promise.',src:'Sloan (1996), Do Stock Prices Fully Reflect Information in Accruals and Cash Flows about Future Earnings?, The Accounting Review 71(3); Schilit, Perler & Engelhart, Financial Shenanigans (4th ed., 2018).'},
 {id:'l5-redflags',t:'12 red flags in financial statements',d:'A checklist before you put money in',
  vis:()=>{ const f=['Profit, but negative CFO','Receivables spike','Large other receivables','Bloated inventory','Gains from asset sales','Short debt, long projects','Constant share issuance','Related-party deals','Qualified audit','Insiders selling','Big post-audit changes','Long-stalled construction'];
    let g=''; f.forEach((t,i)=>{ const x=4+(i%3)*65, y=8+Math.floor(i/3)*28; g+=`<rect x="${x}" y="${y}" width="62" height="24" rx="5" style="fill:var(--s1);stroke:var(--dn)" stroke-opacity=".6"/><path d="M${x+6} ${y+18} V${y+5} l7 3 -7 3" style="fill:var(--dn);stroke:var(--dn)" stroke-width="1"/>`;
      const w=t.split(' '); const l1=w.slice(0,Math.ceil(w.length/2)).join(' '), l2=w.slice(Math.ceil(w.length/2)).join(' '); g+=T(x+37,y+11,l1,'text-anchor="middle" style="font-size:6.2px;font-weight:700"')+T(x+37,y+19,l2,'text-anchor="middle" style="font-size:6.2px;font-weight:700"'); });
    return sv(g,'Twelve common red flags in financial statements'); },
  f:'One red flag = needs an explanation · Three or more = skip it, the market has hundreds of other choices',
  pts:['1. Profit is positive for years but operating cash flow is negative.','2. Trade receivables grow faster than revenue for several periods in a row.','3. Large “other receivables”, “prepayments to suppliers” or “loans” with unclear counterparties.','4. Inventory grows faster than revenue (goods that are hard to sell, may need write-down provisions).','5. Profit comes mainly from asset disposals, revaluations or reversed provisions.','6. Short-term borrowing to fund long-term projects (maturity mismatch, breaks easily when credit tightens).','7. Constant share issuance, diluted EPS, and raised funds used for purposes other than those disclosed.','8. Large transactions with related parties: purchases, sales, loans and guarantees for companies tied to management.','9. Qualified audit opinion, changes of auditor, late filings.','10. Heavy selling by management and major shareholders; pledged shares force-sold by lenders.','11. Audited profit differs significantly from the self-prepared report.','12. Construction in progress and capitalized interest that are large and drag on for years.'],
  thr:[['0 red flags','Go on to valuation'],['1–2 red flags','Look for an explanation in the notes and annual report'],['3+ red flags','Drop it']],
  hook:'<b>Remember:</b> you don’t need to be right on every stock — you only need to avoid the ones that can wipe you out.',src:'Schilit, Perler & Engelhart, Financial Shenanigans (2018); Beneish (1999), The Detection of Earnings Manipulation, Financial Analysts Journal 55(5).'},
 {id:'l5-practice',t:'Practice: read the statements in 15 minutes',d:'A fictional example with a step-by-step solution',interactive:'practice',
  vis:()=>{ const yrs=['2023','2024','2025'], ni=[100,130,180], cfo=[110,60,-20], Y=v=>78-v*0.28; let g=`<line class="grid-l" x1="14" x2="190" y1="${Y(0)}" y2="${Y(0)}"/>`;
    yrs.forEach((y,i)=>{ const x=30+i*56; g+=`<rect x="${x}" y="${Y(ni[i])}" width="18" height="${ni[i]*0.28}" rx="2" style="fill:var(--gold);fill-opacity:.8"/>`+T(x+9,Y(ni[i])-3,ni[i],'text-anchor="middle" style="font-size:7px;font-weight:700"');
      const top=cfo[i]>=0?Y(cfo[i]):Y(0), h=Math.abs(cfo[i])*0.28; g+=`<rect x="${x+20}" y="${top}" width="18" height="${Math.max(1,h)}" rx="2" style="fill:${cfo[i]>=0?'var(--up)':'var(--dn)'};fill-opacity:.8"/>`+T(x+29,cfo[i]>=0?Y(cfo[i])-3:Y(cfo[i])+9,cfo[i],'text-anchor="middle" style="font-size:7px;font-weight:700"')+T(x+19,107,y,'text-anchor="middle" style="font-size:7px"'); });
    g+=T(100,9,'Fictional firm Golden Lotus · Gold: net income · Green/red: CFO','text-anchor="middle" style="font-size:6.4px"')+T(100,120,'Profit up 80% but cash negative — why?','text-anchor="middle" '+TB);
    return sv(g,'Fictional example: profit rising while operating cash flow falls'); },
  f:'6-step process: Growth → Margins → Cash flow → Working capital → Debt → Conclusion',
  pts:['Step 1 — Growth: how much do revenue and profit grow each year, and is it steady?','Step 2 — Margins: are gross and net margins expanding or shrinking?','Step 3 — Cash flow: CFO compared with net income.','Step 4 — Working capital: are receivables and inventory growing faster than revenue? (compute days sales outstanding and days inventory)','Step 5 — Debt: is the cash shortfall covered by borrowing or share issuance; how is debt ÷ equity changing?','Step 6 — Conclude in one sentence: is this growth healthy or “overheated”? Do the exercise below and answer it yourself before revealing the solution.'],
  thr:[['Revenue and CFO rise together','Healthy growth'],['Revenue up, CFO down, debt up','“Overheated” growth, needs an explanation']],
  hook:'<b>Remember:</b> every growth story has to survive the cash flow statement.',src:'Fictional example written by the app for practice; method based on CFA Institute, Financial Reporting and Analysis.'},
 /* ---------- cấp 7: chọn cổ phiếu ---------- */
 {id:'l7-process',t:'A 5-step stock-picking process',d:'From 1,000 stocks down to a few worth buying',act:'screen',
  vis:()=>{ const st=[['1,000 stocks','Quantitative screen',180],['≈ 100','Read statements, red flags',148],['≈ 30','Industry, moat, mgmt',116],['≈ 10','Valuation, safety margin',84],['3–5','Thesis & plan',52]];
    let g=''; st.forEach(([n,t,w],i)=>{ const y=8+i*22, ww=w*0.55, x=52-ww/2; g+=`<path d="M${x} ${y} h${ww} l-9 18 h${-(ww-18)} z" style="fill:var(--gold);fill-opacity:${.6+i*.1}"/>`+T(52,y+12,n,'text-anchor="middle" style="font-size:7.6px;font-weight:800;fill:var(--gold-ink)"')+`<line x1="${52+ww/2-2}" x2="112" y1="${y+9}" y2="${y+9}" style="stroke:var(--line2)" stroke-dasharray="2 2"/>`+T(116,y+12,t,'style="font-size:7px"'); });
    return sv(g,'The five-step stock-picking funnel'); },
  f:'Good business + Fair price + Margin of safety + Clear plan = Investment decision',
  pts:['Step 1 — Quantitative screen: use the Compass screener (try the Value, Quality, Dividend… weight presets) to keep about 100 high-scoring stocks with no red flags.','Step 2 — Read 5 years of financial statements: growth, margins, cash flow, debt (levels 4–5). Drop stocks with 3 or more red flags.','Step 3 — Qualitative: is the industry attractive, does the company have an economic moat, is management trustworthy?','Step 4 — Valuation: P/E and P/B versus history and peers, DCF, reverse valuation. Buy only when the price is below estimated value by a safety margin (usually 20–30%).','Step 5 — Write an investment thesis, set the position size (usually no more than 10–15% of the portfolio in one stock) and the conditions for selling.','Repeat every quarter when new financial statements come out — the watchlist changes over time.'],
  thr:[['Number of stocks to hold','About 8–20 stocks, or one index fund'],['Maximum weight per stock','10–15% of the portfolio'],['Margin of safety','Buy 20–30% below estimated value']],
  hook:'<b>Remember:</b> the more layers in the funnel, the fewer emotional decisions.',src:'Graham & Dodd, Security Analysis (6th ed., 2008); Lynch, One Up on Wall Street (1989); Greenblatt, The Little Book That Still Beats the Market (2010).'},
 {id:'l7-industry',t:'Industry analysis: the 5 competitive forces',d:'A good industry helps a good company win',
  vis:()=>{ let g=AR2; const c=[100,62]; const n=[[100,14,'New entrants','Entry barriers?'],[100,110,'Substitutes','Easy to replace?'],[36,62,'Suppliers','Pricing power?'],[164,62,'Customers','Pricing power?']];
    n.forEach(([x,y,a,b])=>{ g+=`<line x1="${x}" y1="${y}" x2="${c[0]+(x-c[0])*0.32}" y2="${c[1]+(y-c[1])*0.32}" style="stroke:var(--mut)" marker-end="url(#ar2)"/>`+`<rect x="${x-33}" y="${y-10}" width="66" height="20" rx="5" style="fill:var(--s1);stroke:var(--us)"/>`+T(x,y-1,a,'text-anchor="middle" style="font-size:6.2px;font-weight:800"')+T(x,y+7,b,'text-anchor="middle" style="font-size:5.4px;fill:var(--mut)"'); });
    g+=`<circle cx="100" cy="62" r="24" style="fill:var(--gold);fill-opacity:.9"/>`+T(100,60,'Industry','text-anchor="middle" style="font-size:6.2px;font-weight:800;fill:var(--gold-ink)"')+T(100,68,'rivalry','text-anchor="middle" style="font-size:6.2px;font-weight:800;fill:var(--gold-ink)"');
    return sv(g,'Porter’s five competitive forces model'); },
  f:'An industry earns durably high profits when all 5 forces are weak',
  pts:['New entrants: industries that need licenses, big capital or networks (banks, seaports, airports) are harder to enter than easy-to-open ones (coffee shops, garments).','Substitutes: a service that another technology can replace has a hard ceiling on its price.','Strong suppliers (a single source of raw materials) squeeze margins; strong customers (a few big buyers making up most of revenue) squeeze selling prices.','Industry rivalry: identical products, many competitors, high fixed costs (steel, fertilizer, transport) → price wars and cyclical profits.','Cyclical industries (steel, chemicals, shipping, brokerages) usually have their lowest P/E at peak profits and highest at the bottom — counterintuitive.','Use the industry map on the home page to compare the average Compass Score of each industry.'],
  thr:[['High entry barriers','More durable profits'],['Top 3 customers over 50% of revenue','Concentration risk'],['Cyclical industry','Don’t buy because of a low P/E at the cycle peak']],
  hook:'<b>Remember:</b> even a great captain struggles against the tide of a whole industry.',src:'Porter (1979), How Competitive Forces Shape Strategy, Harvard Business Review; Porter (2008), The Five Competitive Forces That Shape Strategy, HBR.'},
 {id:'l7-mgmt',t:'Management, shareholders and governance',d:'Are they in the same boat as you?',
  vis:()=>{ const it=[['Management owns a large stake','y'],['AGM targets usually met','y'],['Steady cash dividends','y'],['Constant issuance, dilution','n'],['Management shares pledged','n'],['Big deals with family firms','n']];
    let g=''; it.forEach(([t,k],i)=>{ const y=12+i*17; g+=`<rect x="10" y="${y-9}" width="180" height="14" rx="4" style="fill:var(--s1);stroke:var(--line)"/><circle cx="20" cy="${y-2}" r="5" style="fill:${k==='y'?'var(--up)':'var(--dn)'}"/>`+T(20,y+1,k==='y'?'✓':'✗','text-anchor="middle" style="font-size:7px;font-weight:800;fill:var(--bg)"')+T(30,y+1,t,'style="font-size:7.2px"'); });
    g+=T(100,118,'Green: good sign · Red: warning sign','text-anchor="middle" '+TS);
    return sv(g,'Corporate governance checklist'); },
  f:'Good governance = Management interests aligned with shareholders + Sensible capital allocation + Transparent disclosure',
  pts:['Read the annual reports and the chair’s/CEO’s letters over many years: do they speak honestly about difficulties, and do they do what they promised?','Compare the profit targets set at shareholder meetings with actual results over 3–5 years.','Capital allocation: is profit used for efficient expansion (high ROIC), dividends — or poured into unrelated ventures and loans to related parties?','Track insider trades (disclosure is mandatory): management buying is usually a better signal than selling.','Management shares pledged for margin loans can be force-sold en masse when the market falls — this has happened many times in Vietnam.','Excessive ESOP issuance, or executive pay rising while profit falls, signals misaligned interests.'],
  thr:[['Management owns over 5–10%','In the same boat as shareholders'],['ESOP over 1–2% a year','Significant dilution'],['Targets met in 4 of 5 years','Management’s forecasts are credible']],
  hook:'<b>Remember:</b> investing in a company means hiring its management to run your money — interview them through what they have done.',src:'Decree 155/2020/ND-CP (governance of public companies); G20/OECD Principles of Corporate Governance (2023).'},
 {id:'l7-sector',t:'Reading statements by industry',d:'Each industry has its own metrics',
  vis:()=>{ const c=[['Banks','var(--us)',['NIM, bad debt','CASA, CAR']],['Real estate','var(--gold)',['Customer advances','Inventory, land bank']],['Retail','var(--up)',['Sales per store','Inventory turnover']],['Industrials','var(--dn)',['Gross margin, capacity','Input prices, capex']],['Brokerages','var(--vn)',['Margin loans','Prop trading']],['Utilities','var(--mut)',['Output, tariffs','Project debt, D&A']]];
    let g=''; c.forEach(([n,col,l],i)=>{ const x=4+(i%3)*65, y=6+Math.floor(i/3)*58; g+=`<rect x="${x}" y="${y}" width="62" height="52" rx="7" style="fill:var(--s1);stroke:${col}"/>`+T(x+31,y+14,n,`text-anchor="middle" style="font-size:7.4px;font-weight:800;fill:${col}"`)+l.map((t,k)=>T(x+31,y+28+k*10,t,'text-anchor="middle" style="font-size:5.4px"')).join(''); });
    return sv(g,'Industry-specific metrics'); },
  f:'Compare a company with peers in the same industry, using that industry’s specific metrics',
  pts:['Banks: don’t use gross margin or debt/equity. Look at NIM (net interest margin), the bad-debt ratio and group-2 (special mention) loans, CASA (current and savings accounts), CAR (capital adequacy ratio), credit costs, P/B.','Real estate: “advances from customers” are future revenue; inventory is projects; clean land bank, project legal status and debt coming due determine the risk. Profit follows handover batches, so it is very lumpy.','Retail: same-store sales growth, inventory turnover, rent as a share of revenue.','Commodity manufacturing (steel, fertilizer, chemicals): gross margin depends on raw material costs and world selling prices; value them through the cycle.','Brokerages: margin loan balance, proprietary trading portfolio (gains and losses follow the market), brokerage market share.','Altman Z and Piotroski scores mean little for insurers and banks — Compass already compares banks only against other banks.'],
  thr:[['Banks: bad debt below 1.5%','Good asset quality'],['Real estate: customer advances rising','Future revenue is secured'],['Retail: inventory turnover falling','Goods are selling slowly']],
  hook:'<b>Remember:</b> don’t measure a bank with a noodle shop’s yardstick.',src:'Circular 41/2016/TT-NHNN (capital adequacy ratios); Damodaran, The Dark Side of Valuation (2018).'},
 {id:'l7-styles',t:'Four stock-picking styles',d:'Value, growth at a reasonable price, growth, dividend',act:'styles',
  vis:()=>{ let g=`<line class="axis" x1="22" x2="190" y1="108" y2="108"/><line class="axis" x1="22" x2="22" y1="10" y2="108"/><line x1="106" x2="106" y1="10" y2="108" style="stroke:var(--line2)" stroke-dasharray="3 3"/><line x1="22" x2="190" y1="59" y2="59" style="stroke:var(--line2)" stroke-dasharray="3 3"/>`;
    const q=[[64,32,'GARP','fast growth, fair price','var(--gold)'],[148,32,'Growth','fast growth, pricey','var(--up)'],[64,82,'Value · Dividend','cheap, slow growth','var(--us)'],[148,82,'Caution','pricey and slow','var(--dn)']];
    q.forEach(([x,y,a,b,c])=>{ g+=T(x,y,a,`text-anchor="middle" style="font-size:8.5px;font-weight:800;fill:${c}"`)+T(x,y+10,b,'text-anchor="middle" style="font-size:6px"'); });
    g+=T(106,121,'Valuation: cheap ← → pricey','text-anchor="middle" '+TS)+`<text transform="translate(12 60) rotate(-90)" text-anchor="middle" style="font-size:6.5px">Growth →</text>`;
    return sv(g,'Map of four stock-picking styles by valuation and growth'); },
  f:'Pick one style that fits your temperament and apply it consistently — switching styles with every fad is the fastest way to lose',
  pts:['Value (Graham): buy companies that are cheap relative to assets and earnings: low P/E, low P/B, a safe balance sheet. Risk: the “value trap” — cheap because it is in decline.','GARP (Lynch): growth at a reasonable price, PEG below 1. A balance between the two schools.','Growth (Fisher, O’Neil): fast-growing revenue and EPS, high ROE; accepts a high P/E. Risk: sharp price drops when growth slows.','Dividend: steady cash flow, high yield, sustainable payouts — suits long-term wealth building and people who need income.','Quality (Buffett): durably high ROIC, little debt, an economic moat — combines well with all four styles.','Tap the buttons below to apply the matching weight preset in the Compass screener.'],
  thr:[['Value','P/E below 12, P/B below 1.5, F-Score 6 or higher'],['Growth','3-year EPS growth over 20%/yr, ROE over 18%'],['Dividend','Yield over 4%, payout below 70%, FCF greater than dividends'],['Quality','ROIC over 15%, debt ÷ equity below 0.5']],
  hook:'<b>Remember:</b> every style has winning years and losing years — discipline is the real edge.',src:'Graham, The Intelligent Investor (1973); Lynch, One Up on Wall Street (1989); Fama & French (1992), The Cross-Section of Expected Stock Returns, Journal of Finance 47(2).'},
 {id:'l7-thesis',t:'Investment thesis and when to sell',d:'Write it down before you buy',
  vis:()=>{ const r=[['I buy because…','3 reasons with data'],['Fair value is…','and margin of safety'],['I am wrong if…','a measurable condition'],['I sell when…','thesis wrong, overpriced'],['Position size…','max % of portfolio']];
    let g=`<rect x="22" y="6" width="156" height="112" rx="8" style="fill:var(--s1);stroke:var(--gold)"/>`+T(100,18,'INVESTMENT THESIS CARD','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--gold)"');
    r.forEach(([a,b],i)=>{ const y=34+i*17; g+=T(30,y,a,'style="font-size:7px;font-weight:800"')+T(170,y,b,'text-anchor="end" style="font-size:6px;fill:var(--mut)"')+`<line x1="30" x2="170" y1="${y+4}" y2="${y+4}" style="stroke:var(--line2)" stroke-dasharray="2 2"/>`; });
    return sv(g,'Investment thesis card template'); },
  f:'Sell when: the thesis is wrong · the price is far above value · there is a clearly better opportunity · you need the money as planned — never just because the price fell',
  pts:['Write a 5-line thesis before buying: why the business is good, why the price is attractive, the catalyst, the main risk, the conditions for selling.','“I am wrong if…” must be measurable: for example “gross margin falls below 20% for two quarters in a row” or “project X is more than 12 months late”.','A falling price is not a reason to sell if the thesis still holds — it may be a chance to buy more. A sharp rise is not a reason to sell either if the business value is rising too.','Percentage stop-losses (e.g. −8%) suit short-term technical trading; long-term investors cut losses when the thesis breaks.','Review the thesis every time quarterly statements come out. Keep a journal: why each decision was right or wrong — this is the fastest way to learn.'],
  thr:[['Thesis still holds, price falls','Hold or buy more up to the planned weight'],['Thesis broken','Sell, even at a loss'],['Price 30%+ above fair value','Consider taking partial profits']],
  hook:'<b>Remember:</b> if you cannot write why you are buying in 5 lines, you don’t understand the business well enough to buy it.',src:'Fisher, Common Stocks and Uncommon Profits (1958); Lynch, One Up on Wall Street (1989); Marks, The Most Important Thing (2011).'},
 /* ---------- cấp 8: tích sản ---------- */
 {id:'l8-plan',t:'A wealth-building plan',d:'Steady contributions + compounding + time',interactive:'fv',
  vis:()=>{ const m=5, r=Math.pow(1.1,1/12)-1; const X=y=>16+y*8.6, Y=v=>104-v/4200*92; let c='',f='';
    for(let y=0;y<=20;y++){ const n=y*12, fv=n? m*((Math.pow(1+r,n)-1)/r):0, ct=m*n; c+=(y?'L':'M')+X(y)+' '+Y(ct); f+=(y?'L':'M')+X(y)+' '+Y(fv); }
    let g=`<path d="${f} L${X(20)} ${Y(0)} L${X(0)} ${Y(0)} Z" style="fill:var(--up);fill-opacity:.35"/><path d="${c} L${X(20)} ${Y(0)} L${X(0)} ${Y(0)} Z" style="fill:var(--us);fill-opacity:.55"/><line class="axis" x1="${X(0)}" x2="${X(20)}" y1="${Y(0)}" y2="${Y(0)}"/>`;
    [0,5,10,15,20].forEach(y=>g+=T(X(y),114,y+' yrs','text-anchor="middle" style="font-size:6px"'));
    g+=T(X(20),Y(3591)-4,'≈ 3.6 bn','text-anchor="end" style="font-size:8px;font-weight:800;fill:var(--up)"')+T(X(20),Y(1200)-4,'1.2 bn paid in','text-anchor="end" style="font-size:7px;font-weight:700;fill:var(--us)"');
    g+=T(16,12,'5M/month · 10%/yr','style="font-size:7.5px;font-weight:800"')+T(16,22,'Green: compounding · Blue: paid in','style="font-size:6.3px"');
    return sv(g,'Building wealth with 5M VND a month for 20 years at a 10% annual return'); },
  f:'Future value = Monthly contribution × [(1 + r)ⁿ − 1] ÷ r  (r: monthly return, n: number of months)',
  pts:['Long-term wealth building means steadily accumulating income-producing assets over many years, not hunting for one stock that goes up 10x.','Three levers: how much you contribute (savings rate), the return, and time — time is the strongest lever because of compounding.','Order of priorities: an emergency fund of 3–6 months of expenses → pay off high-interest debt (credit cards, consumer loans) → regular contributions to the portfolio.','Automate: transfer money on payday; raise your contribution whenever your income rises; reinvest all dividends.','Don’t break the chain: withdrawing midway or stopping contributions when the market falls is the most effective way to destroy compounding.','Use the calculator below to try your own amount, time horizon and return; the result also shows the value in today’s money (after inflation).'],
  thr:[['Savings rate','20% of income or more'],['Conservative return assumption','6–8%/yr for a balanced portfolio'],['Review the plan','Once a year, not every day']],
  hook:'<b>Remember:</b> the winner in wealth building is not the best stock picker, but the one who doesn’t quit the longest.',src:'Future value of an annuity formula; Bogle, The Little Book of Common Sense Investing (2017).'},
 {id:'l8-alloc',t:'Asset allocation',d:'The most important decision for your portfolio',
  vis:()=>{ const P=[['Conservative',[30,50,10,10]],['Balanced',[60,30,5,5]],['Growth',[85,10,5,0]]], C=['var(--up)','var(--us)','var(--mut)','var(--gold)']; let g='';
    P.forEach(([n,a],k)=>{ const cx=34+k*66, cy=50, R=24; let ang=-Math.PI/2; a.forEach((v,i)=>{ if(!v) return; const e=ang+v/100*2*Math.PI; const x1=cx+R*Math.cos(ang), y1=cy+R*Math.sin(ang), x2=cx+R*Math.cos(e), y2=cy+R*Math.sin(e); g+=`<path d="M${cx} ${cy} L${x1.toFixed(1)} ${y1.toFixed(1)} A${R} ${R} 0 ${v>50?1:0} 1 ${x2.toFixed(1)} ${y2.toFixed(1)} Z" style="fill:${C[i]};fill-opacity:.8;stroke:var(--s1)" stroke-width="1"/>`; ang=e; });
      g+=`<circle cx="${cx}" cy="${cy}" r="11" style="fill:var(--s1)"/>`+T(cx,cy+3,a[0]+'%','text-anchor="middle" style="font-size:7px;font-weight:800"')+T(cx,88,n,'text-anchor="middle" style="font-size:7.5px;font-weight:800"'); });
    ['Stocks','Bonds, deposits','Cash','Gold'].forEach((t,i)=>{ const x=30+(i%2)*80, y=100+Math.floor(i/2)*11; g+=`<rect x="${x}" y="${y}" width="7" height="7" rx="2" style="fill:${C[i]}"/>`+T(x+10,y+6.5,t,'style="font-size:6.4px"'); });
    g+=T(100,12,'Three model portfolios','text-anchor="middle" '+TB);
    return sv(g,'Three model asset allocation portfolios'); },
  f:'Rule of thumb: % in stocks ≈ 110 − your age, then adjust for risk appetite and goals',
  pts:['Asset allocation means dividing money between asset classes: stocks, bonds/deposits, cash, gold, real estate. Classic research shows most of a portfolio’s variability comes from this decision, not from picking stocks.','Stocks: the growth engine. Bonds and deposits: dampen swings and give you cash to buy when the market falls. Gold: a hedge against crises and inflation. Cash: liquidity.','Diversify geographically: combining Vietnamese and international stocks avoids depending on a single economy.','Real estate often makes up most of a Vietnamese household’s wealth — count it when deciding your stock allocation.','Reduce the stock allocation as the date you need the money approaches (e.g. retirement, buying a home) — this is called a glide path.'],
  thr:[['Age 30, money not needed for 20 years','70–90% stocks'],['Age 50','50–60% stocks'],['Money needed within 3 years','Under 30% stocks for that portion']],
  hook:'<b>Remember:</b> choosing the right baskets matters more than choosing the right eggs.',src:'Brinson, Hood & Beebower (1986), Determinants of Portfolio Performance, Financial Analysts Journal 42(4); Vanguard Research, The global case for strategic asset allocation (2023).'},
 {id:'l8-rebal',t:'Portfolio rebalancing',d:'Selling high and buying low, with discipline',
  vis:()=>{ const bars=[['Target',60],['After stocks rally',72],['After rebalancing',60]]; let g='';
    bars.forEach(([n,v],i)=>{ const x=20+i*60; g+=`<rect x="${x}" y="${20}" width="34" height="${v*0.8}" rx="2" style="fill:var(--up);fill-opacity:.75"/><rect x="${x}" y="${20+v*0.8}" width="34" height="${(100-v)*0.8}" rx="2" style="fill:var(--us);fill-opacity:.6"/>`+T(x+17,20+v*0.4,v+'%','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--bg)"')+T(x+17,20+v*0.8+(100-v)*0.4+3,(100-v)+'%','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--bg)"')+T(x+17,110,n.split(' ').slice(0,2).join(' '),'text-anchor="middle" style="font-size:6.3px"')+T(x+17,118,n.split(' ').slice(2).join(' '),'text-anchor="middle" style="font-size:6.3px"'); });
    g+=T(100,12,'Green: stocks · Blue: bonds, deposits','text-anchor="middle" style="font-size:6.8px"');
    return sv(g,'Stock weight drifts up to 72% and is rebalanced back to 60%'); },
  f:'Rebalance when a weight drifts more than ±5 percentage points from target, or on a schedule once a year',
  pts:['When stocks rally, the stock weight overshoots its target → the portfolio is riskier than you intended. Rebalancing means trimming what went up and buying what went down.','It is a disciplined way to “buy low, sell high” without having to predict the market.','The cheapest way: use new contributions and dividends to buy the underweight part instead of selling (avoids taxes and fees).','Calendar-based (yearly) or threshold-based (±5 percentage points of drift) both work; rebalancing too often just costs fees.','Apply it inside the stock portfolio too: if one stock grows to more than 15–20% of the portfolio, consider trimming it.'],
  thr:[['Drift under 5 percentage points','Leave it'],['Drift over 5 percentage points','Rebalance'],['One stock over 20% of the portfolio','Concentration risk — consider trimming']],
  hook:'<b>Remember:</b> rebalancing is the discipline of selling when others are greedy and buying when others are fearful — on a schedule, not on emotion.',src:'Vanguard Research, Best practices for portfolio rebalancing (2022 update); Swensen, Unconventional Success (2005).'},
 {id:'l8-dividend',t:'Building wealth with dividends',d:'Dividend reinvestment and yield on cost',
  vis:()=>{ let g=''; const yrs=[0,2,4,6,8,10]; yrs.forEach((y,i)=>{ const sh=1000*Math.pow(1.06,y), x=14+i*31, h=sh/1800*62; g+=`<rect x="${x}" y="${94-h}" width="22" height="${h}" rx="2" style="fill:var(--gold);fill-opacity:${.45+i*.1}"/>`+T(x+11,90-h,Math.round(sh),'text-anchor="middle" style="font-size:6.8px;font-weight:700"')+T(x+11,103,'yr '+y,'text-anchor="middle" style="font-size:6px"'); });
    g+=T(100,10,'1,000 shares, 6%/yr dividend, all reinvested','text-anchor="middle" style="font-size:7px;font-weight:800"')+T(100,116,'Shares up ≈ 79% in 10 yrs, before price gains','text-anchor="middle" '+TS);
    return sv(g,'Reinvesting dividends steadily grows the share count'); },
  f:'Yield on cost = Current dividend per share ÷ Original purchase price · Total return = Price gain + Dividends',
  pts:['Reinvesting dividends (buying more shares with the dividend cash) makes your share count grow by itself — compounding with the company raising its dividend over time.','Over the long run, reinvested dividends have contributed a very large share of the US stock market’s total return.','Yield on cost: bought at 20,000, current dividend 2,000 → 10% on your original cost, even though the yield on the market price is only 4%.','Pick durable dividend stocks: payout ratio below 70%, FCF greater than dividends, low debt, a steady payment history. Avoid the “dividend trap”: a very high yield because the price has collapsed.','In Vietnam, cash dividends are subject to 5% withholding tax; stock dividends don’t make you richer at the moment they are paid (the price adjusts accordingly).'],
  thr:[['Dividend yield 3–6%','The common sustainable range'],['Over 10%','Check it: may be a dividend trap'],['Dividend raised many years in a row','Sign of a quality company']],
  hook:'<b>Remember:</b> dividends are “hens that lay eggs” — while building wealth, don’t eat the eggs, hatch more hens.',src:'Siegel, Stocks for the Long Run (6th ed., 2022); S&P Dow Jones Indices, dividend contribution research.'},
 {id:'l8-fire',t:'Financial independence and the 4% rule',d:'How much you need to live off your assets',
  vis:()=>{ let g=AR2; g+=`<rect x="12" y="34" width="56" height="40" rx="7" style="fill:var(--s1);stroke:var(--us)"/>`+T(40,48,'Spending/yr','text-anchor="middle" style="font-size:7px;font-weight:800;fill:var(--us)"')+T(40,62,'300M','text-anchor="middle" style="font-size:9px;font-weight:800"');
    g+=T(80,57,'× 25','text-anchor="middle" style="font-size:10px;font-weight:800"');
    g+=`<rect x="94" y="22" width="94" height="64" rx="9" style="fill:var(--gold);fill-opacity:.85"/>`+T(141,42,'Target assets','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--gold-ink)"')+T(141,62,'7.5 bn','text-anchor="middle" style="font-size:15px;font-weight:800;fill:var(--gold-ink)"')+T(141,76,'withdraw 4% in year 1','text-anchor="middle" style="font-size:6.5px;fill:var(--gold-ink)"');
    g+=T(100,104,'Withdrawals rise with inflation each year','text-anchor="middle" '+TS)+T(100,116,'More cautious: 3–3.5% (× 29–33)','text-anchor="middle" '+TB);
    return sv(g,'Target assets equal one year of spending times 25'); },
  f:'Target assets ≈ One year of spending × 25  (i.e. withdraw 4% in year one, then raise it with inflation)',
  pts:['Bengen’s research (1994) and the “Trinity Study” (1998) on US data: withdrawing 4% of assets in year one, then adjusting for inflation, from a balanced stock–bond portfolio almost always lasted 30 years.','To live off your assets for longer than 30 years, or in a more volatile market, use a more cautious 3–3.5% withdrawal rate.','Example: spending 300M VND a year → you need about 7.5 bn (4%) to 10 bn (3%).','Combine this with the Wealth-building plan lesson: once you know the destination, work backward to the monthly contribution and number of years needed.','Other income (pension, rent, a business) reduces the assets you need.','This is a rule of thumb based on US history, with no guarantee for the future or for the Vietnamese market.'],
  thr:[['Withdraw 4%','Assets = 25 × spending'],['Withdraw 3.5%','≈ 29 × spending'],['Withdraw 3%','≈ 33 × spending']],
  hook:'<b>Remember:</b> financial independence starts with knowing how much you spend each year.',src:'Bengen (1994), Determining Withdrawal Rates Using Historical Data, Journal of Financial Planning; Cooley, Hubbard & Walz (1998), Retirement Savings: Choosing a Withdrawal Rate That Is Sustainable, AAII Journal.'}
];
LESSONS2.forEach(l=>{ l.g='Extended'; LESSONS.push(l); });

